import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    try:
        data = json.loads(ip_address)
    except json.JSONDecodeError:
        return 'Invalid IP address received'
    value = data.get('ip', '')
    match = re.search(IP_REGEX, str(value))
    if not match:
        return 'Invalid IP address received'
    ip = match.group(0)
    parts = ip.split('.')
    if len(parts) != 4:
        return 'Invalid IP address received'
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        return 'Invalid IP address received'
    for n in nums:
        if n < 0 or n > 255:
            return 'Invalid IP address received'
    return ip

