import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception('Invalid URL')
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
    except Exception as e:
        raise Exception('URL cannot be accessed') from e
    if not response.ok:
        raise Exception('URL cannot be accessed')
    try:
        data = response.json()
    except ValueError as e:
        raise Exception('Invalid data') from e
    if not data:
        raise Exception('Empty data')
    try:
        if isinstance(data, dict):
            if 'data' in data and isinstance(data['data'], (list, dict)):
                df = pd.DataFrame(data['data'])
            else:
                df = pd.DataFrame(data)
        else:
            df = pd.DataFrame(data)
    except Exception as e:
        raise Exception('Invalid data') from e
    if df.empty:
        raise Exception('Empty data')
    numeric_df = df.select_dtypes(include='number')
    if numeric_df.empty:
        raise Exception('Invalid data')
    corr = numeric_df.corr()
    ax = sns.heatmap(corr, annot=False, cmap='viridis')
    ax.figure.tight_layout()
    ax.figure.canvas.draw()
    return df, ax

