import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json
def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, body_dict):
            body = json.dumps(body_dict).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        def do_POST(self):
            try:
                content_length = self.headers.get("Content-Length")
                if content_length is None:
                    raise ValueError("Missing Content-Length header")
                length = int(content_length)
                raw_data = self.rfile.read(length)
                try:
                    data = json.loads(raw_data.decode("utf-8"))
                except json.JSONDecodeError as e:
                    self._send_response(400, {"error": "Invalid JSON"})
                    raise
                required_keys = ["subject", "message", "to"]
                if not all(k in data for k in required_keys):
                    self._send_response(400, {"error": "Missing required fields"})
                    raise ValueError("Missing subject, message, or to")
                subject = data["subject"]
                message = data["message"]
                to_addr = data["to"]
                msg = MIMEText(message)
                msg["Subject"] = subject
                msg["From"] = smtp_username
                msg["To"] = to_addr
                try:
                    with smtplib.SMTP(smtp_server, smtp_port) as server:
                        server.starttls()
                        server.login(smtp_username, smtp_password)
                        server.sendmail(smtp_username, [to_addr], msg.as_string())
                except smtplib.SMTPAuthenticationError as e:
                    self._send_response(535, {"error": "Authentication Failed"})
                    raise
                self._send_response(200, {"status": "Email sent"})
            except ValueError:
                if not self.wfile.closed:
                    pass
            except json.JSONDecodeError:
                if not self.wfile.closed:
                    pass
            except smtplib.SMTPAuthenticationError:
                if not self.wfile.closed:
                    pass
    return EmailRequestHandler

