        data = json.loads(json_str)
    except json.JSONDecodeError:
        data = None
    email_pattern = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
    values = []
    def process(value):
        if value is None:
            return None
        if isinstance(value, dict):
            new_dict = {}
            for k, v in value.items():
                processed_v = process(v)
                if processed_v is not None:
                    new_dict[k] = processed_v
            return new_dict
        if isinstance(value, list):
            return [process(v) for v in value]
        if isinstance(value, tuple):
            return tuple(process(v) for v in value)
        if isinstance(value, str):
            if email_pattern.fullmatch(value):
                values.append(REPLACE_NONE)
                return REPLACE_NONE
            values.append(value)
            return value
        values.append(value)
        return value
    processed_data = process(data)
    value_counts = Counter(values)
    return {"data": processed_data, "value_counts": value_counts}

